# Busca binária: complexidade de tempo O(log n) e espaço O(1)
def busca_binaria(vetor_ordenado: list[int], alvo: int) -> int:
    inicio, fim = 0, len(vetor_ordenado) - 1
    while inicio <= fim:
        meio = (inicio + fim) // 2
        if vetor_ordenado[meio] == alvo:
            return meio  # Índice encontrado
        elif vetor_ordenado[meio] < alvo:
            inicio = meio + 1
        else:
            fim = meio - 1
    return -1  # Não encontrado

