# O(2ⁿ) Recursão ingênua com árvore de chamadas redundantes
def fib_exponencial(n: int) -> int:
    if n <= 1: return n
    return fib_exponencial(n - 1) + fib_exponencial(n - 2)

# O(n) Otimizado com Memoization (Programação Dinâmica)
def fib_memo(n: int, cache: dict = None) -> int:
    if cache is None: cache = {}
    if n in cache: return cache[n]
    if n <= 1: return n
    cache[n] = fib_memo(n - 1, cache) + fib_memo(n - 2, cache)
    return cache[n]

# O(n) espaço auxiliar: cria uma nova lista clonada
def inverter_com_copia(arr: list[int]) -> list[int]:
    return [arr[i] for i in range(len(arr) - 1, -1, -1)]

# O(1) espaço auxiliar: inverte in-place usando two pointers
def inverter_in_place(arr: list[int]) -> None:
    i, j = 0, len(arr) - 1
    while i < j:
        arr[i], arr[j] = arr[j], arr[i]
        i += 1
        j -= 1

# Simulação conceitual de vetor dinâmico com realocação geométrica
class VetorDinamico:
    def __init__(self):
        self.capacidade = 2
        self.tamanho = 0
        self.dados = [None] * self.capacidade

    def append(self, valor):
        if self.tamanho == self.capacidade:
            self.capacidade *= 2  # Fator de crescimento 2x
            novo = [None] * self.capacidade
            for i in range(self.tamanho):
                novo[i] = self.dados[i]
            self.dados = novo
        self.dados[self.tamanho] = valor
        self.tamanho += 1  # Custo amortizado: O(1)

