# Localiza dois números em array ordenado que somam o alvo em O(n)
def two_sum_ordenado(nums: list[int], alvo: int) -> list[int]:
    esquerda, direita = 0, len(nums) - 1
    while esquerda < direita:
        soma = nums[esquerda] + nums[direita]
        if soma == alvo:
            return [esquerda, direita]
        elif soma < alvo:
            esquerda += 1  # Precisamos de um valor maior
        else:
            direita -= 1   # Precisamos de um valor menor
    return []

# Comprimento da maior substring sem repetição de caracteres: O(n)
def sub_sem_repeticao(texto: str) -> int:
    posicoes = {}
    inicio = 0
    maior_comprimento = 0

    for fim, char in enumerate(texto):
        if char in posicoes and posicoes[char] >= inicio:
            # Contrai a janela pulando o início para após a repetição
            inicio = posicoes[char] + 1
        posicoes[char] = fim
        maior_comprimento = max(maior_comprimento, fim - inicio + 1)

    return maior_comprimento

def remover_por_valor(head: ListNode, alvo: int) -> ListNode | None:
    if head and head.val == alvo:
        return head.next  # Nova cabeça

    prev = head
    curr = head.next if head else None
    while curr:
        if curr.val == alvo:
            prev.next = curr.next  # Bypassa e desconecta o nó alvo
            break
        prev = curr
        curr = curr.next
    return head

class DoublyNode:
    def __init__(self, val=0, prev=None, next=None):
        self.val = val
        self.prev = prev
        self.next = next

# Remoção O(1) de um nó com referência direta
def remover_no(no: DoublyNode) -> None:
    if no.prev:
        no.prev.next = no.next
    if no.next:
        no.next.prev = no.prev
    no.prev = None
    no.next = None

# Remove todos os nós com determinado valor sem casos especiais de cabeça
def remover_todos(head: ListNode, val: int) -> ListNode | None:
    dummy = ListNode(0, head)
    curr = dummy
    while curr.next:
        if curr.next.val == val:
            curr.next = curr.next.next  # Bypassa nó sem checar se era a cabeça
        else:
            curr = curr.next
    return dummy.next  # Retorna a cabeça verdadeira resultante

# Detecta presença de ciclo em lista encadeada em O(n) tempo e O(1) espaço
def tem_ciclo(head: ListNode) -> bool:
    slow = head
    fast = head
    while fast and fast.next:
        slow = slow.next       # 1 nó por iteração
        fast = fast.next.next  # 2 nós por iteração
        if slow == fast:
            return True        # Colisão confirmada: há ciclo!
    return False               # Atingiu None: lista linear acíclica

# Implementação conceitual de Pilha usando array subjacente
class Pilha:
    def __init__(self):
        self._itens = []

    def push(self, valor):
        self._itens.append(valor)  # O(1) amortizado

    def pop(self):
        if not self._itens: raise IndexError("Pilha vazia")
        return self._itens.pop()   # O(1) remoção do topo

    def peek(self):
        return self._itens[-1] if self._itens else None

# Validação de delimitadores balanceados em O(n) tempo e O(n) espaço
def eh_valido(s: str) -> bool:
    pares = {')': '(', ']': '[', '}': '{'}
    pilha = []
    for char in s:
        if char in pares.values():
            pilha.append(char)  # Caractere de abertura vai para a pilha
        elif char in pares:
            # Caractere de fechamento exige correspondente no topo
            if not pilha or pilha.pop() != pares[char]:
                return False
    return len(pilha) == 0

class QueueWithStacks:
    def __init__(self):
        self.in_stack = []
        self.out_stack = []

    def push(self, x: int) -> None:
        self.in_stack.append(x)  # Enfileirar é sempre O(1)

    def pop(self) -> int:
        if not self.out_stack:
            # Inverte a ordem transferindo os elementos
            while self.in_stack:
                self.out_stack.append(self.in_stack.pop())
        return self.out_stack.pop()  # Custo médio amortizado: O(1)

# Encontra o próximo elemento maior à direita para cada item em O(n)
def next_greater_element(nums: list[int]) -> list[int]:
    resultado = [-1] * len(nums)
    pilha = []  # Armazena índices em ordem decrescente de valor

    for i, valor in enumerate(nums):
        while pilha and nums[pilha[-1]] < valor:
            indice_topo = pilha.pop()
            resultado[indice_topo] = valor  # Encontrou o próximo maior!
        pilha.append(i)

    return resultado

# Tabela Hash com Separate Chaining (buckets contendo listas encadeadas)
class HashTableChaining:
    def __init__(self, size=10):
        self.size = size
        self.buckets = [[] for _ in range(size)]

    def put(self, key, value):
        idx = hash(key) % self.size
        for item in self.buckets[idx]:
            if item[0] == key:
                item[1] = value  # Atualiza chave existente
                return
        self.buckets[idx].append([key, value])  # Insere no encadeamento

# Sondagem Linear simplificada para inserção em Open Addressing
def inserir_open_addressing(tabela: list, chave: str, valor: any) -> None:
    tamanho = len(tabela)
    idx = hash(chave) % tamanho

    for _ in range(tamanho):
        if tabela[idx] is None or tabela[idx] == "<DELETED>":
            tabela[idx] = (chave, valor)  # Slot livre encontrado
            return
        idx = (idx + 1) % tamanho  # Salto linear para o próximo slot
    raise OverflowError("Tabela Hash completamente cheia!")

