# Busca em BST com complexidade média O(log n)
def buscar_bst(raiz: TreeNode | None, alvo: int) -> TreeNode | None:
    curr = raiz
    while curr and curr.val != alvo:
        if alvo < curr.val:
            curr = curr.left   # Descarta subárvore direita
        else:
            curr = curr.right  # Descarta subárvore esquerda
    return curr  # Retorna o nó ou None se não existir

