# BFS: Travessia por níveis usando Fila FIFO em tempo O(n)
def travessia_niveis(raiz: TreeNode | None) -> list[list[int]]:
    if not raiz: return []
    resultado, fila = [], deque([raiz])

    while fila:
        nivel_atual = []
        for _ in range(len(fila)):
            no = fila.popleft()
            nivel_atual.append(no.val)
            if no.left: fila.append(no.left)
            if no.right: fila.append(no.right)
        resultado.append(nivel_atual)
    return resultado

