# Encontra os K maiores elementos com Min-Heap: O(n log k) tempo, O(k) espaço
def top_k_maiores(nums: list[int], k: int) -> list[int]:
    min_heap = []
    for num in nums:
        heapq.heappush(min_heap, num)
        if len(min_heap) > k:
            heapq.heappop(min_heap)  # Descarta o menor dos k+1
    return min_heap

