import heapq

class MedianFinder:
    def __init__(self):
        self.pequenos = []  # Max-Heap (armazena valores com sinal invertido)
        self.grandes = []   # Min-Heap

    def add_num(self, num: int) -> None:
        # Adiciona e balanceia entre os dois heaps em O(log n)
        heapq.heappush(self.pequenos, -num)
        heapq.heappush(self.grandes, -heapq.heappop(self.pequenos))
        if len(self.grandes) > len(self.pequenos):
            heapq.heappush(self.pequenos, -heapq.heappop(self.grandes))

    def find_median(self) -> float:
        if len(self.pequenos) > len(self.grandes):
            return float(-self.pequenos[0])
        return (-self.pequenos[0] + self.grandes[0]) / 2.0

