# BFS para menor caminho em grafo não ponderado: O(V + E)
def menor_caminho_bfs(grafo: dict, inicio: str, destino: str) -> int:
    fila = deque([(inicio, 0)])  # Tupla (vertice, distancia)
    visitados = {inicio}

    while fila:
        atual, dist = fila.popleft()
        if atual == destino: return dist
        for vizinho in grafo.get(atual, []):
            if vizinho not in visitados:
                visitados.add(vizinho)
                fila.append((vizinho, dist + 1))
    return -1

