# Algoritmo de Dijkstra com Min-Heap para menor caminho com pesos positivos
def dijkstra(grafo: dict, origem: str) -> dict:
    distancias = {v: float('inf') for v in grafo}
    distancias[origem] = 0
    pq = [(0, origem)]  # (distancia_acumulada, vertice)

    while pq:
        dist_atual, u = heapq.heappop(pq)
        if dist_atual > distancias[u]: continue
        for vizinho, peso in grafo[u]:
            if distancias[u] + peso < distancias[vizinho]:
                distancias[vizinho] = distancias[u] + peso
                heapq.heappush(pq, (distancias[vizinho], vizinho))
    return distancias

# Detecção de ciclo em grafo direcionado com 3 estados (Branco, Cinza, Preto)
def tem_ciclo_direcionado(grafo: dict) -> bool:
    BRANCO, CINZA, PRETO = 0, 1, 2
    estado = {u: BRANCO for u in grafo}

    def dfs(u):
        estado[u] = CINZA  # Entra na pilha de recursão
        for v in grafo.get(u, []):
            if estado[v] == CINZA: return True  # Ciclo detectado!
            if estado[v] == BRANCO and dfs(v): return True
        estado[u] = PRETO  # Totalmente explorado
        return False

    return any(estado[u] == BRANCO and dfs(u) for u in grafo)

# Selection Sort in-place: O(n²) tempo e O(1) espaço auxiliar
def selection_sort(arr: list[int]) -> None:
    n = len(arr)
    for i in range(n):
        min_idx = i
        for j in range(i + 1, n):
            if arr[j] < arr[min_idx]:
                min_idx = j
        # Executa a troca in-place
        arr[i], arr[min_idx] = arr[min_idx], arr[i]

# Insertion Sort in-place: O(n) no melhor caso, O(n²) no pior caso
def insertion_sort(arr: list[int]) -> None:
    for i in range(1, len(arr)):
        chave = arr[i]
        j = i - 1
        # Desloca elementos maiores que a chave para a direita
        while j >= 0 and arr[j] > chave:
            arr[j + 1] = arr[j]
            j -= 1
        arr[j + 1] = chave

# Particionamento in-place de Lomuto: O(n) tempo e O(1) espaço
def particionar_lomuto(arr: list[int], low: int, high: int) -> int:
    pivo = arr[high]  # Escolhe o último como pivô
    i = low
    for j in range(low, high):
        if arr[j] < pivo:
            arr[i], arr[j] = arr[j], arr[i]
            i += 1
    arr[i], arr[high] = arr[high], arr[i]  # Coloca pivô na posição final
    return i

# Matriz de Prefixo (Prefix Sum): gasta espaço O(n) para consultas O(1)
class PrefixSum:
    def __init__(self, nums: list[int]):
        self.pref = [0]
        for n in nums: self.pref.append(self.pref[-1] + n)

    def query(self, left: int, right: int) -> int:
        # Retorna soma da fatia [left, right] em tempo O(1) instantâneo
        return self.pref[right + 1] - self.pref[left]

# Estrutura híbrida clássica de Cache LRU com operações O(1)
class LRUNode:
    def __init__(self, k=0, v=0):
        self.k, self.v = k, v
        self.prev = self.next = None

class LRUCache:
    def __init__(self, capacity: int):
        self.cap = capacity
        self.cache = {}  # key -> LRUNode para busca O(1)
        self.head, self.tail = LRUNode(), LRUNode()
        self.head.next, self.tail.prev = self.tail, self.head

# Problema do Troco: Abordagem gulosa falha com moedas não canônicas [1, 3, 4]
# Troco de 6: Guloso daria 4 + 1 + 1 (3 moedas). O ótimo global é 3 + 3 (2 moedas)!
def troco_minimo_dp(moedas: list[int], quantia: int) -> int:
    dp = [float('inf')] * (quantia + 1)
    dp[0] = 0
    for i in range(1, quantia + 1):
        for m in moedas:
            if i >= m: dp[i] = min(dp[i], dp[i - m] + 1)
    return dp[quantia] if dp[quantia] != float('inf') else -1

